INSERT INTO districts (state_id, name, code) VALUES (9, 'North Goa', 'GA_NORTHGOA') ON CONFLICT (code) DO NOTHING;
INSERT INTO districts (state_id, name, code) VALUES (9, 'South Goa', 'GA_SOUTHGOA') ON CONFLICT (code) DO NOTHING;
